from lesson_helpers import *
pop=[]
def add(k,title,body,ids):pop.append('<template data-pop="n00-'+k+'" data-title="'+html.escape(title,quote=True)+'">'+body+ref(*ids)+'</template>')
add('nephritique-nephrotique','Néphritique et néphrotique : distinguer sans opposer', '''<p>Le syndrome néphritique met au premier plan une hématurie glomérulaire, une protéinurie et un retentissement inflammatoire rénal ou hydrosodé. Le syndrome néphrotique met au premier plan une protéinurie importante et une hypoalbuminémie. L’œdème peut être présent dans les deux ; il ne suffit donc pas à les séparer.</p><p>Les formes mixtes existent. Mesurer la protéinurie et l’albuminémie permet de reconnaître une composante néphrotique et d’en discuter les risques propres. Les seuils diffèrent selon âge, méthode et référentiel ; un chiffre de protéinurie n’identifie pas à lui seul la cause histologique.</p><p>Conséquence : ne pas appliquer automatiquement le traitement d’un syndrome néphrotique idiopathique à une hématurie avec insuffisance rénale aiguë. Le sédiment et la dynamique de fonction restent déterminants.</p>''',('EU-SYNDROMES','EU-HISTO'))
add('sediment','Acanthocytes et cylindres : indices de localisation', '''<p>Un acanthocyte est une hématie dysmorphique dont les protrusions orientent vers un passage glomérulaire. Les HUG retiennent notamment plus de5% d’acanthocytes ou des cylindres hématiques comme arguments d’origine glomérulaire. La méthode, la fraîcheur du prélèvement et sa concentration influencent la morphologie.</p><p>Un cylindre érythrocytaire est un moulage tubulaire contenant des hématies. Il apporte un argument fort pour une origine intrarénale de type glomérulaire dans ce contexte. Des cellules libres agglutinées ne constituent pas automatiquement un cylindre.</p><p>L’absence de ces signes n’exclut pas la maladie : leur sensibilité est limitée. La protéinurie, la fonction et la clinique permettent d’interpréter un sédiment pauvre ou équivoque.</p>''',('CH-SEDIMENT','INT-GN-GENERAL','EU-HEMATURIA'))
add('croissant','Croissant extracapillaire : lieu, activité, conséquence', '''<p>Le croissant se développe dans l’espace urinaire de Bowman lorsque des lésions capillaires sévères entraînent une réaction cellulaire extracapillaire. Les cellules épithéliales pariétales, les cellules inflammatoires et la fibrine participent à cette lésion. Il ne s’agit pas simplement d’un glomérule « plus gros ».</p><p>Une lésion cellulaire active et une cicatrice fibreuse ne sont pas équivalentes pour le pronostic. La biopsie précise l’étendue des lésions et leurs caractères ; un seul champ photographique ne permet pas de quantifier la proportion de croissants dans tous les reins.</p><p>Plusieurs maladies peuvent produire des croissants. L’immunofluorescence, les anticorps et le contexte infectieux ou systémique orientent la cause et le traitement. Le mot « croissant » n’autorise pas une immunosuppression uniforme.</p>''',('CH-URGENCE','EU-RPGN','INT-INFECTION'))
add('calcul-ratio','Rapport protéines/créatinine : calcul et limites', '''<p><b>Grandeurs.</b> La concentration de protéines urinaires est exprimée enmg/L ; la créatinine urinaire enmmol/L. Les deux proviennent du même prélèvement. Leur rapport réduit l’effet de dilution commun, sans supprimer la variabilité biologique.</p><p><b>Formule.</b> Rapport enmg/mmol = protéines enmg/L ÷ créatinine enmmol/L. Le litre est au numérateur et au dénominateur : il s’annule.</p><p><b>Exemple fictif.</b>1200mg/L ÷6mmol/L =200mg/mmol. Le résultat n’est ni une concentration de200mg/L, ni une excrétion de200mg/24h. Pour interpréter, préciser protéinurie totale ou albuminurie, âge et contexte.</p><p>Un prélèvement ponctuel peut varier ; chez l’enfant, le premier matin est souvent privilégié. Chez l’adulte, un recueil prolongé peut être nécessaire si la décision d’intensifier un traitement dépend d’une quantification précise. Ne pas comparer des unités différentes sans conversion validée.</p>''',('INT-GN-GENERAL','EU-SYNDROMES'))
add('cas-1','Cas 1 — La priorité est la menace respiratoire', '''<p><b>Question originale.</b> Une personne présente des urines sombres, une créatinine ascendante et une dyspnée nouvelle. Faut-il attendre la sérologie antistreptococcique avant d’orienter ?</p><p><b>Réponse raisonnée : non.</b> Évaluer immédiatement respiration, saturation, pression, état circulatoire, diurèse, potassium et fonction. La surcharge pulmonaire est une possibilité ; une hémorragie alvéolaire doit aussi être envisagée dans un contexte glomérulaire rapide. Une atteinte menaçante nécessite une prise en charge hospitalière urgente.</p><p>Les prélèvements de cause se poursuivent en parallèle. Une sérologie ne sécurise pas la respiration et son résultat ne doit pas devenir un préalable à l’orientation. Le raisonnement porte d’abord sur l’organe menacé, puis sur la cause qui déterminera le traitement spécifique.</p>''',('CH-URGENCE','EU-RPGN','EU-IRA'))
add('cas-2','Cas 2 — Des ANCA ne suffisent pas à décider', '''<p><b>Question originale.</b> Une personne avec hématurie glomérulaire, fièvre prolongée et souffle cardiaque a des ANCA positifs. Peut-on conclure à une vascularite primaire ?</p><p><b>Réponse raisonnée : pas sur ce résultat seul.</b> KDIGO rapporte des ANCA dans certaines glomérulonéphrites d’endocardite. Le contexte impose de rechercher une infection active : microbiologie, foyer et exploration cardiaque selon l’évaluation clinique. La biopsie peut aider à comprendre la lésion rénale.</p><p>Le piège serait une immunosuppression automatique fondée sur un test positif. La conduite correcte articule recherche infectieuse, évaluation rénale urgente et décision spécialisée ; elle ne consiste ni à ignorer la vascularite possible, ni à négliger l’infection.</p>''',('INT-INFECTION','EU-RPGN'))
add('cas-3','Cas 3 — Suivi du complément et dynamique rénale', '''<p><b>Question originale.</b> Le C3 reste bas après une hypothèse de glomérulonéphrite postinfectieuse. La créatinine augmente à nouveau. Faut-il attendre douze semaines avant de réévaluer ?</p><p><b>Réponse raisonnée : non.</b> La persistance d’un C3 bas au-delà de douze semaines est un repère pouvant conduire à une biopsie pour rechercher notamment une maladie du complément. Ce repère n’est pas un délai d’attente obligatoire. Une aggravation de fonction ou une présentation atypique justifie une réévaluation plus précoce.</p><p>Suivre conjointement fonction, pression, diurèse et protéinurie. Le complément apporte un indice sur la trajectoire immunologique, mais ne remplace pas les signes d’atteinte active ni les décisions urgentes.</p>''',('INT-INFECTION','CH-ORIENTATION'))
add('cas-4','Cas 4 — Deux calculs, deux questions', '''<p><b>Données fictives.</b> Un adulte de70kg émet200mL en8h ; son échantillon urinaire contient1200mg/L de protéines et6mmol/L de créatinine.</p><p><b>Diurèse.</b> Diviser le volume par le temps puis par le poids :200÷8=25mL/h ;25÷70≈0,36mL/kg/h. Ce résultat est inférieur à0,5mL/kg/h pendant une fenêtre de8h, si le recueil est fiable. Il répond à une question de fonction et de sévérité aiguë.</p><p><b>Protéinurie.</b>1200÷6=200mg/mmol. Le rapport répond à une question de fuite protéique. Il ne donne pas le volume urinaire, et le premier calcul ne quantifie pas les protéines.</p><p><b>Interprétation.</b> Retenir le stade le plus sévère entre critères de créatinine et de diurèse, vérifier la fiabilité des mesures et rechercher la cause. Aucun de ces calculs ne remplace l’examen clinique ou le sédiment.</p>''',('INT-AKI','INT-GN-GENERAL'))
save('pop1','\n'.join(pop[:4]));save('pop2','\n'.join(pop[4:]));print(len(pop),'fenêtres rédigées')
